  Tensor(Tensor &&tensor) noexcept;
  Tensor &operator=(Tensor &&tensor) noexcept;

  virtual ~Tensor();

  void create(const std::string &name);

  void create(const TensorDesc &desc, const std::string &name = "");
  void create(const TensorDesc &desc, Buffer *buffer,
              const std::string &name = "");

  void create(Device *device, const TensorDesc &desc,
              const std::string &name = "",
              const nndeploy::base::IntVector &config = nndeploy::base::IntVector());
  void create(Device *device, const TensorDesc &desc, void *data_ptr,
              const std::string &name = "",
              const nndeploy::base::IntVector &config = nndeploy::base::IntVector());

  void create(MemoryPool *memory_pool, const TensorDesc &desc,
              const std::string &name = "",
              const nndeploy::base::IntVector &config = nndeploy::base::IntVector());
  void create(MemoryPool *memory_pool, const TensorDesc &desc, void *data_ptr,
              const std::string &name = "",
              const nndeploy::base::IntVector &config = nndeploy::base::IntVector());

  void clear();

  void allocate(Device *device,
                const nndeploy::base::IntVector &config = nndeploy::base::IntVector());
  void allocate(MemoryPool *memory_pool,
                const nndeploy::base::IntVector &config = nndeploy::base::IntVector());
  void deallocate();

  template <typename T>
  nndeploy::base::Status set(T value) {
    if (buffer_ == nullptr) {
      NNDEPLOY_LOGE("buffer_ is empty");
      return nndeploy::base::kStatusCodeErrorNullParam;
    }

    return buffer_->set(value);
  }

  nndeploy::base::Status reshape(nndeploy::base::IntVector shape);
  bool justModify(const TensorDesc &desc);
  bool justModify(Buffer *buffer, bool is_external = true);

  Tensor *clone();
  nndeploy::base::Status copyTo(Tensor *dst);

  nndeploy::base::Status serialize(std::string &bin_str);
#ifdef ENABLE_NNDEPLOY_SAFETENSORS_CPP
  nndeploy::base::Status serializeToSafetensors(safetensors::safetensors_t &st,
                                      bool serialize_buffer = false);
#endif
  nndeploy::base::Status deserialize(const std::string &bin_str);
#ifdef ENABLE_NNDEPLOY_SAFETENSORS_CPP
  nndeploy::base::Status serializeFromSafetensors(const safetensors::safetensors_t &st);
#endif

  void print(std::ostream &stream = std::cout) const;

  bool isSameDevice(Tensor *tensor) const;
  bool isSameMemoryPool(Tensor *tensor) const;
  bool isSameDesc(Tensor *tensor) const;

  bool empty() const;
  bool isContinue() const;
  bool isExternalBuffer() const;

  std::string getName() const;
  nndeploy::base::Status setName(const std::string &);
  TensorDesc getDesc() const;
  nndeploy::base::DataType getDataType() const;
  void setDataType(nndeploy::base::DataType data_type);
  nndeploy::base::DataFormat getDataFormat() const;
  void setDataFormat(nndeploy::base::DataFormat data_format);
  nndeploy::base::IntVector getShape() const;
  int getShapeIndex(int index) const;
  int getBatch() const;
  int getChannel() const;
  int getDepth() const;
  int getHeight() const;
  int getWidth() const;
  nndeploy::base::SizeVector getStride() const;
  size_t getStrideIndex(int index) const;

  Buffer *getBuffer() const;
  nndeploy::base::DeviceType getDeviceType() const;
  Device *getDevice() const;
  MemoryPool *getMemoryPool() const;
  bool isMemoryPool() const;
  BufferDesc getBufferDesc() const;
  size_t getSize() const;
  nndeploy::base::SizeVector getSizeVector() const;
  size_t getRealSize() const;
  nndeploy::base::SizeVector getRealSizeVector() const;
  nndeploy::base::IntVector getConfig() const;
  void *getData() const;
  nndeploy::base::MemoryType getMemoryType() const;

  template <typename T, typename... Args>
  T *getPtr(Args... args) {
    uint8_t *ptr = reinterpret_cast<uint8_t *>(getData());
    if (ptr == nullptr) {
      NNDEPLOY_LOGE("Tensor data is empty\n");
      return nullptr;
    }

    int coord[] = {std::forward<int>(args)...};
    int dims = static_cast<int>(sizeof...(args));
    if (dims > static_cast<int>(desc_.shape_.size())) {
      NNDEPLOY_LOGE("dimension %d is out of range with shape size %d\n", dims,
                    static_cast<int>(desc_.shape_.size()));
      return nullptr;
    }

    size_t offset = 0;
    for (int i = 0; i < dims; ++i) {
      if (coord[i] < 0 || coord[i] >= desc_.shape_[i]) {
        NNDEPLOY_LOGE("index: %d is out of range for dimension %d with size %d\n",
                      coord[i], i, desc_.shape_[i]);
        return nullptr;
      }
      offset += coord[i] * desc_.stride_[i];
    }

    return reinterpret_cast<T *>(ptr + offset);
  }

#ifdef ENABLE_NNDEPLOY_SAFETENSORS_CPP
  static nndeploy::base::Status dtype2SafetensorsDtype(
      const nndeploy::base::DataType &data_type,
      safetensors::dtype &safetensors_data_type);
  static nndeploy::base::Status shape2SafetensorsShape(
      const nndeploy::base::IntVector &shape,
      std::vector<size_t> &safetensors_data_shape);

  static nndeploy::base::Status safetensorsDtype2Dtype(
      const safetensors::dtype &safetensors_data_type,
      nndeploy::base::DataType &data_type);

  static nndeploy::base::Status safetensorsShape2Shape(
      const std::vector<size_t> &safetensors_data_shape,
      nndeploy::base::IntVector &shape);
#endif

  inline int addRef() const { return NNDEPLOY_XADD(ref_count_, 1); }
  inline int subRef() const { return NNDEPLOY_XADD(ref_count_, -1); }

 private:
  std::string name_ = "";
  TensorDesc desc_;
  bool is_external_ = false;
  int *ref_count_ = nullptr;
  Buffer *buffer_ = nullptr;
};

